import pandas as pd, numpy as np, os, json, math, random, itertools, sys, pathlib, pickle, glob, re, string
# Load datasets
DATASET_PATH = 'chunks_csv/moran_local_2022_ghg.csv'
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# Build undirected neighbor list
neighbors = {b:set() for b in df['borough']}
for _, row in adj.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in neighbors:
        neighbors[b].add(n)
    else:
        neighbors[b]={n}
    if n in neighbors:
        neighbors[n].add(b)
    else:
        neighbors[n]={b}

# Verify all boroughs have at least one neighbor
print("Number of boroughs:", len(neighbors))
print("Boroughs with zero neighbors:", [b for b,l in neighbors.items() if len(l)==0])

# Prepare z-scores
mean_val = df['GHG_value'].mean()
std_val  = df['GHG_value'].std(ddof=1)
df['z'] = (df['GHG_value'] - mean_val) / std_val

# Map borough -> z
z_dict = dict(zip(df['borough'], df['z']))

# Row-standardized weights and compute observed I_i and spatial lag
I_obs = {}
lag_z = {}
for b in neighbors:
    neighs = neighbors[b]
    if len(neighs)==0:
        I_obs[b]=0
        lag_z[b]=0
        continue
    weight = 1.0/len(neighs)
    lag = sum(z_dict[n]*weight for n in neighs if n in z_dict)
    lag_z[b] = lag
    I_obs[b] = z_dict[b]*lag

# Permutation test
perms = 999
I_perm_distributions = {b:[] for b in neighbors}
z_values = list(z_dict.values())
boroughs = list(neighbors.keys())

rng = np.random.default_rng(42)
for p in range(perms):
    rng.shuffle(z_values)
    z_shuff = dict(zip(boroughs, z_values))
    for b in boroughs:
        neighs = neighbors[b]
        if len(neighs)==0:
            I_perm_distributions[b].append(0)
            continue
        weight = 1.0/len(neighs)
        lag_perm = sum(z_shuff[n]*weight for n in neighs)
        I_perm_distributions[b].append(z_shuff[b]*lag_perm)

# Compute p-values
p_values = {}
for b in boroughs:
    I_obs_val = I_obs[b]
    perm_vals = I_perm_distributions[b]
    extreme = sum(abs(v) >= abs(I_obs_val) for v in perm_vals)
    p = (extreme + 1) / (perms + 1)
    p_values[b]=p

# Identify hot/cold spots
hot_cold = {}
for b in boroughs:
    if p_values[b] < 0.05:
        if z_dict[b] > 0 and lag_z[b] > 0:
            hot_cold[b]=('HH', I_obs[b])
        elif z_dict[b] < 0 and lag_z[b] < 0:
            hot_cold[b]=('LL', I_obs[b])

print("Significant borough clusters:", hot_cold)

# Build final answer line
if not hot_cold:
    final_line = "FINAL ANSWER: none"
else:
    parts=[]
    for b,(label,val) in hot_cold.items():
        parts.append(f"{b} ({label}, Local Moran I={val:.3f})")
    final_line = "FINAL ANSWER: " + ", ".join(parts)

print(final_line)
